--- /etc/nginx/sites-available/set12-a.test.conf (on this server)
+++ CelikPanel's text
@@ -1,9 +1,47 @@
-# set10: the server owner's own vhost for set12-a.test, written by hand
+# Nginx vhost for set12-a.test
+# Written by CelikPanel. Put your own additions in /etc/nginx/celikpanel-sites.d/set12-a.test/*.conf;
+# CelikPanel never writes there. If you change this file, CelikPanel keeps
+# your file and asks you before it replaces it. Keep the lines that include
+# /etc/nginx/celikpanel-managed.d/set12-a.test: that directory is CelikPanel's (certificate
+# validation) and CelikPanel writes there without touching this file.
+# CelikPanel yazdı. Kendi eklemeleriniz /etc/nginx/celikpanel-sites.d/set12-a.test/*.conf içine;
+# CelikPanel oraya hiç yazmaz. Bu dosyayı değiştirirseniz CelikPanel
+# dosyanızı korur ve değiştirmeden önce size sorar. /etc/nginx/celikpanel-managed.d/set12-a.test
+# satırlarını koruyun: o dizin CelikPanel'indir (sertifika doğrulaması).
+# Site ID: 2 · Project type: php
 server {
     listen 80;
     listen [::]:80;
-    server_name set12-a.test;
+    server_name set12-a.test www.set12-a.test;
+
+    access_log /var/log/nginx/set12-a.test-access.log;
+    error_log /var/log/nginx/set12-a.test-error.log;
+
+    # CelikPanel's own parts of this site (certificate validation) / CelikPanel'in parçaları
+    include /etc/nginx/celikpanel-managed.d/set12-a.test/*.conf;
+
+    root /var/www/celikpanel/subscriptions/2/sites/2/public_html;
+    index index.php index.html index.htm;
+
     location / {
-        return 200 "owner-replaced\n";
+
+        try_files $uri $uri/ /index.php?$query_string;
     }
+    location ~ \.php$ {
+        fastcgi_split_path_info ^(.+?\.php)(/.*)$;
+        try_files $fastcgi_script_name =404;
+        set $path_info $fastcgi_path_info;
+        fastcgi_param PATH_INFO $path_info;
+        fastcgi_index index.php;
+        include fastcgi.conf;
+        fastcgi_pass unix:/var/run/php/php8.3-fpm-site2.sock;
+        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
+        include fastcgi_params;
+    }
+    location ~ /\.(?!well-known).* {
+        deny all;
+    }
+
+    # Your additions for this site (server context) / Bu site için eklemeleriniz
+    include /etc/nginx/celikpanel-sites.d/set12-a.test/*.conf;
 }

